WITH base AS (SELECT *, TRIM(device_code) clean_device_code, TO_DATE(reading_ts) reading_ts_date FROM device_readings WHERE reading_ts >= '2023-12-04') SELECT CASE WHEN temp_c >= 38.8 THEN 'PREMIUM' ELSE 'STANDARD' END AS temp_c_tier, SUM(CASE WHEN device_code = 'DV-01' THEN temp_c ELSE 0 END) AS dv_01_temp_c, STDDEV_SAMP(humidity) AS humidity_stddev FROM base GROUP BY CASE WHEN temp_c >= 38.8 THEN 'PREMIUM' ELSE 'STANDARD' END;
